CREATE SCHEMA IF NOT EXISTS industrendindia AUTHORIZATION CURRENT_USER;
SET search_path TO industrendindia,pg_catalog;
CREATE TABLE IF NOT EXISTS customers(customer_id uuid PRIMARY KEY,mobile_e164 varchar(16) NOT NULL UNIQUE,first_name varchar(80),last_name varchar(80),email varchar(254),mobile_verified_at timestamptz NOT NULL,email_verified_at timestamptz,profile_completed_at timestamptz,status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','LOCKED','DELETED')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),CONSTRAINT customers_email_format CHECK(email IS NULL OR email ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'));
CREATE UNIQUE INDEX IF NOT EXISTS customers_email_uq ON customers(lower(email)) WHERE email IS NOT NULL;
CREATE TABLE IF NOT EXISTS customer_addresses(address_id uuid PRIMARY KEY,customer_id uuid NOT NULL REFERENCES customers(customer_id) ON DELETE CASCADE,address_type varchar(20) NOT NULL DEFAULT 'DELIVERY',address_line1 varchar(240) NOT NULL,area_landmark varchar(240),city varchar(100) NOT NULL,state_name varchar(100) NOT NULL,postal_code char(6) NOT NULL CHECK(postal_code ~ '^[1-9][0-9]{5}$'),is_default boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX IF NOT EXISTS customer_addresses_customer_idx ON customer_addresses(customer_id); CREATE UNIQUE INDEX IF NOT EXISTS customer_default_address_uq ON customer_addresses(customer_id) WHERE is_default;
CREATE TABLE IF NOT EXISTS otp_challenges(challenge_id uuid PRIMARY KEY,destination varchar(254) NOT NULL,channel varchar(12) NOT NULL CHECK(channel IN('SMS','EMAIL')),purpose varchar(24) NOT NULL CHECK(purpose IN('LOGIN','MOBILE_CHANGE','EMAIL_CHANGE')),otp_hash char(64) NOT NULL,expires_at timestamptz NOT NULL,attempt_count smallint NOT NULL DEFAULT 0,max_attempts smallint NOT NULL DEFAULT 5,consumed_at timestamptz,verified_at timestamptz,verified_customer_id uuid REFERENCES customers(customer_id),requested_ip inet,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX IF NOT EXISTS otp_destination_created_idx ON otp_challenges(destination,created_at DESC); CREATE INDEX IF NOT EXISTS otp_expiry_idx ON otp_challenges(expires_at) WHERE consumed_at IS NULL;
CREATE TABLE IF NOT EXISTS postal_code_reference(postal_code char(6) PRIMARY KEY CHECK(postal_code ~ '^[1-9][0-9]{5}$'),city varchar(100) NOT NULL,state_name varchar(100) NOT NULL,active boolean NOT NULL DEFAULT true); CREATE INDEX IF NOT EXISTS postal_code_city_state_idx ON postal_code_reference(state_name,city);
CREATE TABLE IF NOT EXISTS customer_sessions(session_id uuid PRIMARY KEY,customer_id uuid NOT NULL REFERENCES customers(customer_id) ON DELETE CASCADE,token_hash char(64) NOT NULL UNIQUE,csrf_hash char(64) NOT NULL,user_agent_hash char(64),ip_created inet,expires_at timestamptz NOT NULL,last_seen_at timestamptz NOT NULL DEFAULT clock_timestamp(),revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX IF NOT EXISTS customer_sessions_customer_idx ON customer_sessions(customer_id,expires_at DESC); CREATE INDEX IF NOT EXISTS customer_sessions_active_idx ON customer_sessions(token_hash,expires_at) WHERE revoked_at IS NULL;
